#include <stdio.h>
#include <ctype.h>
#include <string.h>
int main(void) {
    char buf[1024];
    fgets(buf, sizeof(buf), stdin);
    int len = strlen(buf);
    if (len > 0 && buf[len-1] == '\n') buf[--len] = '\0';
    int word_count = 0, total_length = 0, current_length = 0, longest = 0, in_word = 0;
    for (int i = 0; i <= len; i++) {
        if (i < len && !isspace((unsigned char)buf[i])) {
            if (!in_word) { in_word = 1; current_length = 0; word_count++; }
            current_length++;
        } else if (in_word) {
            in_word = 0;
            total_length += current_length;
            if (current_length > longest) longest = current_length;
        }
    }
    double avg = word_count > 0 ? (double)total_length / word_count : 0.0;
    printf("Words: %d\nLongest: %d\nAverage: %.2f\n", word_count, longest, avg);
    return 0;
}

