    char buf[1024];
    fgets(buf, sizeof(buf), stdin);
    int len = strlen(buf);
    if (len > 0 && buf[len-1] == '\n') buf[--len] = '\0';
    int words = 1;
    int longest = 0, current = 0, total = 0;
    for (int i = 0; i < len; i++) {
        if (buf[i] == ' ') {
            words++;
            if (current > longest) longest = current;
            total += current;
            current = 0;
        } else current++;
    }
    if (current > longest) longest = current;
    total += current;
    float avg = (float)total / words;
    printf("Words: %d\nLongest: %d\nAverage: %.2f\n", words, longest, avg);
    return 0;
}

